import { withDrafts } from './draft-glyphs.ts';
import { DRAFT_LEVEL_GLYPHS } from './draft-level-glyphs.ts';
import { DRAFT_MAP_GLYPHS } from './draft-map-glyphs.ts';
import raw from './templates.json';
import { parseTemplates } from './templates.ts';
import type { Templates } from './types.ts';

const HARVESTED = parseTemplates(raw);

/**
 * The shipped Classic-client templates: generated by scripts/harvest-templates.mjs, plus hand-drawn
 * drafts for text-font, map-font and level-font characters not harvested yet (see draft-glyphs.ts,
 * draft-map-glyphs.ts and draft-level-glyphs.ts). Harvested glyphs always win.
 */
export const DEFAULT_TEMPLATES: Templates = {
  ...HARVESTED,
  fonts: {
    ...HARVESTED.fonts,
    text: withDrafts(HARVESTED.fonts.text),
    map: withDrafts(HARVESTED.fonts.map, DRAFT_MAP_GLYPHS),
    level: withDrafts(HARVESTED.fonts.level, DRAFT_LEVEL_GLYPHS),
  },
};
